mod solution;

fn main() {
    let cases = [
    (r#"edges=(0,1),(1,2),(2,0),(2,3)"#, r#"true"#),
    (r#"edges=(0,1),(1,2)"#, r#"false"#),
    (r#"
edges=(0,1),(1,2)
"#, r#"false"#),
    (r#"  
edges=(0,1),(1,2),(2,0),(2,3)
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS undirected-cycle");
}
